CREATE TYPE "status_post" AS ENUM (
  'rascunho',
  'agendado',
  'publicado',
  'arquivado'
);

CREATE TYPE "papel_usuario" AS ENUM (
  'admin',
  'editor'
);

CREATE TYPE "acao_post" AS ENUM (
  'criou',
  'editou',
  'publicou',
  'agendou',
  'despublicou',
  'arquivou',
  'excluiu'
);

CREATE TABLE "usuarios" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nome" varchar(120) NOT NULL,
  "email" varchar(254) UNIQUE NOT NULL,
  "senha_hash" varchar(255) NOT NULL,
  "papel" papel_usuario NOT NULL DEFAULT 'editor',
  "ativo" boolean NOT NULL DEFAULT true,
  "versao_sessao" integer NOT NULL DEFAULT 1,
  "ultimo_acesso_em" timestamptz,
  "criado_em" timestamptz NOT NULL DEFAULT (now()),
  "editado_em" timestamptz NOT NULL DEFAULT (now())
);

CREATE TABLE "autores" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nome" varchar(120) NOT NULL,
  "cargo" varchar(80) NOT NULL,
  "foto_url" varchar(500),
  "bio" text,
  "registro" varchar(60),
  "usuario_id" integer UNIQUE,
  "ativo" boolean NOT NULL DEFAULT true,
  "criado_em" timestamptz NOT NULL DEFAULT (now())
);

CREATE TABLE "categorias" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "slug" varchar(80) UNIQUE NOT NULL,
  "nome" varchar(80) NOT NULL,
  "descricao" text,
  "ordem" integer NOT NULL DEFAULT 0,
  "criado_em" timestamptz NOT NULL DEFAULT (now())
);

CREATE TABLE "posts" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "slug" varchar(160) UNIQUE NOT NULL,
  "titulo" varchar(200) NOT NULL,
  "resumo" varchar(320) NOT NULL,
  "conteudo" text NOT NULL,
  "capa_url" varchar(500),
  "capa_alt" varchar(200),
  "categoria_id" integer NOT NULL,
  "autor_id" integer NOT NULL,
  "status" status_post NOT NULL DEFAULT 'rascunho',
  "destaque" boolean NOT NULL DEFAULT false,
  "tempo_leitura_min" integer NOT NULL DEFAULT 1,
  "publicado_em" timestamptz,
  "atualizado_em" timestamptz,
  "criado_por_id" integer NOT NULL,
  "editado_por_id" integer NOT NULL,
  "publicado_por_id" integer,
  "criado_em" timestamptz NOT NULL DEFAULT (now()),
  "editado_em" timestamptz NOT NULL DEFAULT (now())
);

CREATE TABLE "posts_historico" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "post_id" integer,
  "usuario_id" integer NOT NULL,
  "acao" acao_post NOT NULL,
  "titulo" varchar(200) NOT NULL,
  "dados" jsonb,
  "criado_em" timestamptz NOT NULL DEFAULT (now())
);

CREATE INDEX "idx_posts_listagem" ON "posts" ("status", "publicado_em");

CREATE INDEX "idx_posts_categoria" ON "posts" ("categoria_id");

CREATE INDEX "idx_posts_autor" ON "posts" ("autor_id");

CREATE INDEX "idx_historico_post" ON "posts_historico" ("post_id", "criado_em");

CREATE INDEX "idx_historico_usuario" ON "posts_historico" ("usuario_id");

COMMENT ON COLUMN "usuarios"."email" IS 'Usado no login; salvar em minúsculas';

COMMENT ON COLUMN "usuarios"."senha_hash" IS 'Hash bcrypt/argon2. Nunca a senha em texto';

COMMENT ON COLUMN "usuarios"."ativo" IS 'Desativar em vez de excluir, para manter o histórico';

COMMENT ON COLUMN "usuarios"."versao_sessao" IS 'Somar 1 derruba todas as sessões do usuário';

COMMENT ON COLUMN "autores"."cargo" IS 'Ex.: Sócio';

COMMENT ON COLUMN "autores"."foto_url" IS 'Sem foto, o site mostra a inicial do nome';

COMMENT ON COLUMN "autores"."registro" IS 'Ex.: CRC-PE 000000/O-0';

COMMENT ON COLUMN "autores"."usuario_id" IS 'Opcional: autor que também acessa o painel';

COMMENT ON COLUMN "categorias"."ordem" IS 'Ordem dos filtros na listagem';

COMMENT ON COLUMN "posts"."resumo" IS 'Usado no card e na meta description';

COMMENT ON COLUMN "posts"."conteudo" IS 'HTML sanitizado (h2, h3, p, ul, ol, blockquote, a, strong, img)';

COMMENT ON COLUMN "posts"."capa_url" IS 'Sem capa, o site mostra o placeholder em degradê';

COMMENT ON COLUMN "posts"."autor_id" IS 'Quem ASSINA o artigo no site';

COMMENT ON COLUMN "posts"."destaque" IS 'Só um post deve ficar em destaque';

COMMENT ON COLUMN "posts"."publicado_em" IS 'Data exibida no site; futura = agendado';

COMMENT ON COLUMN "posts"."atualizado_em" IS 'Revisão de conteúdo exibida ao leitor ("Atualizado em")';

COMMENT ON COLUMN "posts"."criado_por_id" IS 'Usuário que criou o post no painel';

COMMENT ON COLUMN "posts"."editado_por_id" IS 'Último usuário que salvou';

COMMENT ON COLUMN "posts"."publicado_por_id" IS 'Usuário que publicou ou agendou por último';

COMMENT ON COLUMN "posts"."editado_em" IS 'Controle interno de qualquer alteração';

COMMENT ON COLUMN "posts_historico"."post_id" IS 'Fica vazio se o post for excluído; o histórico continua';

COMMENT ON COLUMN "posts_historico"."titulo" IS 'Título no momento da ação (identifica posts já excluídos)';

COMMENT ON COLUMN "posts_historico"."dados" IS 'Cópia do post após a ação: permite ver e restaurar versões';

ALTER TABLE "posts" ADD FOREIGN KEY ("categoria_id") REFERENCES "categorias" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "posts" ADD FOREIGN KEY ("autor_id") REFERENCES "autores" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "posts" ADD FOREIGN KEY ("criado_por_id") REFERENCES "usuarios" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "posts" ADD FOREIGN KEY ("editado_por_id") REFERENCES "usuarios" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "posts" ADD FOREIGN KEY ("publicado_por_id") REFERENCES "usuarios" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "posts_historico" ADD FOREIGN KEY ("post_id") REFERENCES "posts" ("id") ON DELETE SET NULL DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "autores" ADD FOREIGN KEY ("usuario_id") REFERENCES "usuarios" ("id") ON DELETE SET NULL DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "posts_historico" ADD FOREIGN KEY ("usuario_id") REFERENCES "usuarios" ("id") DEFERRABLE INITIALLY IMMEDIATE;
